from dataclasses import dataclass
from datetime import datetime
from typing import Any

from packaging.specifiers import InvalidSpecifier, SpecifierSet
from packaging.version import InvalidVersion, Version


def _parse_datetime(value: Any) -> datetime | None:
    """Parse a PyPI ``upload_time_iso_8601`` value, returning ``None`` if invalid."""
    if not isinstance(value, str) or not value:
        return None
    # ``datetime.fromisoformat`` on older Python versions does not accept a
    # trailing ``Z``, so normalize it to an explicit UTC offset.
    text = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        return datetime.fromisoformat(text)
    except ValueError:
        return None


def _parse_requires_python(dists: list[dict[str, Any]]) -> SpecifierSet | None:
    """Return the first non-empty, valid ``requires_python`` across distributions."""
    for dist in dists:
        raw = dist.get("requires_python")
        if not raw:
            continue
        try:
            return SpecifierSet(raw)
        except InvalidSpecifier:
            continue
    return None


@dataclass(frozen=True)
class Release:
    """A single package release (one version)."""

    version: Version
    upload_time: datetime
    yanked: bool
    requires_python: SpecifierSet | None

    @classmethod
    def from_json(cls, version: Version, dists: list[dict[str, Any]]) -> Release | None:
        """Build a ``Release`` from a version and its list of distribution dicts.

        Returns ``None`` when the release should be dropped (no distributions, or
        no distribution with a parseable ``upload_time_iso_8601``).
        """
        if not dists:
            return None

        upload_times = [
            ut for dist in dists if (ut := _parse_datetime(dist.get("upload_time_iso_8601")))
        ]
        if not upload_times:
            return None

        return cls(
            version=version,
            upload_time=min(upload_times),
            # A release is yanked only if *every* distribution is yanked.
            yanked=all(bool(dist.get("yanked", False)) for dist in dists),
            requires_python=_parse_requires_python(dists),
        )


@dataclass(frozen=True)
class Package:
    """A PyPI package and its releases."""

    name: str
    releases: dict[Version, Release]

    @classmethod
    def from_json(cls, data: dict[str, Any]) -> Package:
        name = (data.get("info") or {}).get("name", "")
        releases: dict[Version, Release] = {}
        for version_str, dists in (data.get("releases") or {}).items():
            try:
                version = Version(version_str)
            except InvalidVersion:
                continue
            release = Release.from_json(version, dists or [])
            if release is not None:
                releases[version] = release
        return cls(name=name, releases=releases)

    @property
    def versions(self) -> tuple[Version, ...]:
        return tuple(sorted(self.releases))

    @property
    def latest_version(self) -> Version | None:
        candidates = [
            version
            for version, release in self.releases.items()
            if not version.is_prerelease and not version.is_devrelease and not release.yanked
        ]
        return max(candidates) if candidates else None

    def get_release(self, version: str | Version) -> Release | None:
        if isinstance(version, str):
            try:
                version = Version(version)
            except InvalidVersion:
                return None
        return self.releases.get(version)
