import asyncio
import json
import os
import time
import urllib.error
import urllib.request
from collections.abc import Iterable

from pypi._models import Package

DEFAULT_BASE_URL = "https://pypi.org"

# Status codes that are worth retrying.
_RETRYABLE_STATUS = frozenset({429, 500, 502, 503, 504})

# Maximum total number of attempts (initial request + retries).
_MAX_ATTEMPTS = 3


class PyPIError(RuntimeError):
    """Raised for all unrecoverable errors when fetching from PyPI."""


# In-memory cache mapping package name -> Package.
_cache: dict[str, Package] = {}


def _base_url() -> str:
    override = os.environ.get("PYPI_URL")
    if override:
        return override.rstrip("/")
    return DEFAULT_BASE_URL


def _fetch_json(name: str) -> bytes:
    """Fetch the raw JSON body for ``name`` from PyPI, with retries."""
    url = f"{_base_url()}/pypi/{name}/json"
    last_error: BaseException | None = None
    for attempt in range(1, _MAX_ATTEMPTS + 1):
        try:
            with urllib.request.urlopen(url) as response:
                return response.read()
        except urllib.error.HTTPError as e:
            if e.code == 404:
                raise PyPIError(f"Package not found: {name!r}") from e
            if e.code not in _RETRYABLE_STATUS:
                raise PyPIError(f"HTTP {e.code} while fetching {name!r}") from e
            last_error = e
        except (urllib.error.URLError, ConnectionResetError) as e:
            last_error = e

        if attempt < _MAX_ATTEMPTS:
            time.sleep(2 ** (attempt - 1))

    raise PyPIError(
        f"Failed to fetch {name!r} after {_MAX_ATTEMPTS} attempts"
    ) from last_error


def get_package(name: str) -> Package:
    """Fetch package metadata from the PyPI JSON API, memoizing the result."""
    if name in _cache:
        return _cache[name]

    data = json.loads(_fetch_json(name))
    if not isinstance(data, dict):
        raise PyPIError(f"Unexpected response for {name!r}: expected a JSON object")

    package = Package.from_json(data)
    _cache[name] = package
    return package


def clear_cache() -> None:
    """Clear the in-memory cache used by :func:`get_package`."""
    _cache.clear()


async def aget_package(name: str) -> Package:
    """Async wrapper around :func:`get_package`."""
    return await asyncio.to_thread(get_package, name)


async def aget_packages(names: Iterable[str]) -> list[Package]:
    """Fetch multiple packages concurrently, preserving input order."""
    names = list(names)
    return list(await asyncio.gather(*(aget_package(name) for name in names)))
